import random

def binary_search(a, target):
    """Return (index or -1, comparisons used)."""
    lo, hi = 0, len(a) - 1
    comparisons = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        comparisons += 1
        if a[mid] == target:
            return mid, comparisons
        elif a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, comparisons

a = list(range(0, 200, 2))          # even numbers 0..198, sorted
for target in (0, 76, 198, 77):
    idx, used = binary_search(a, target)
    where = f"index {idx}" if idx >= 0 else "not found"
    print(f"search {target:3d}: {where:>11s}  ({used} comparisons, list of {len(a)})")
